+/// Controlled mod-add with an optional SCHEDULE carry-cap `k`. `Some(k)` (the
+/// apply cofactor add) emits the adaptive cout decomposition at the baked `k`.
+/// `None` (the off-peak coordinate steps) uses the local exact cout adder.
+pub fn controlled_mod_add_k(circ: &mut B, ctrl: &QubitId, x: &[QubitId], y: &[QubitId], sched_k: Option<usize>, ffg_g: Option<usize>) {
+    let n = x.len();
+    assert_eq!(y.len(), n, "x,y must both be n=256 bits");
+    assert_eq!(n, 256, "secp256k1 controlled_mod_add expects n=256");
+    let f_bytes = F_SECP256K1.to_le_bytes();
+    let anc = circ.alloc_qubit();
+    // 1) y += ctrl*x; carry-out (overflow) captured into the transient anc.
+    match sched_k {
+        Some(k) => {
+            let yr: Vec<&QubitId> = y.iter().collect();
+            let xr: Vec<&QubitId> = x.iter().collect();
+            super::gidney::controlled_hybrid_add_cout_refs(circ, ctrl, &yr, &xr, &anc, k);
+        }
+        None => controlled_add_vented_chunked_cout(circ, ctrl, x, y, APPLY_CHUNK, Some(&anc)),
+    }
+    // 2) gated +f reduction (anc holds ctrl AND overflow); carry beyond LSBS dropped.
+    add_f_window(circ, &anc, y, LSBS, &f_bytes, ffg_g);
+    // 3) less-than comparator erases anc back to |0>: anc holds `ctrl AND (y_final < x)`. The
+    //    ludicrous profile truncates this comparator to the top `MSBS = PAD = 21`
+    //    bits and clears the flag by measurement-vent (HMR + gated top-k Z), not a
+    //    normal full-width comparator + `zero_and_free`. The HMR never asserts
+    //    |0>, so the ~2^-MSBS top-k mis-clear is tolerated (the schedule-sim's
+    //    CMP/PAD term accounts for it). ~21 vs ~256 CCX per call (the full-width
+    //    k=256 normal form), on ~half the shots.
+    debug_assert_eq!(MSBS, PAD); // the +f comparator is truncated to the top PAD bits
+    // The less-than erase consumes `anc`: it HMRs it then frees it BEFORE the recompute
+    // comparator (so the overflow flag is not held live across the chunked comparator).
+    controlled_lt_msbs_conditional(circ, Some(ctrl), &y[..n], &x[..n], MSBS, anc);
+}

+/// Compress 3 base-5 symbols (s0 on `w[0..3]`, s1 on `w[3..6]`, s2 on `w[6..9]`)
+/// plus 2 clean ancilla (`w[9]`, `w[10]`) into a 7-bit code on
+/// [`TRIPLE_DATA_WIRES`]. [`TRIPLE_FREED_WIRES`] -> |0>, ancilla restored.
+fn compress_3sym(circ: &mut B, w: &[&QubitId; 11]) {
+    compress_2sym_fast(circ, &[w[0], w[1], w[2], w[3], w[4], w[5]]);
+    for &op in NORMALIZER_OPS {
+        apply_op_off(circ, &w[..], op, 6);
+    }
+    apply_merge25(circ, &w[..], 6, false);
+}
+
+/// Decompress: inverse of [`compress_3sym`] (ops reversed; X/CX/CCX self-inverse).
+fn compress_3sym_reverse(circ: &mut B, w: &[&QubitId; 11]) {
+    apply_merge25(circ, &w[..], 6, true);
+    for &op in NORMALIZER_OPS.iter().rev() {
+        apply_op_off(circ, &w[..], op, 6);
+    }
+    compress_2sym_fast_reverse(circ, &[w[0], w[1], w[2], w[3], w[4], w[5]]);
+}

+/// Product-min secp256k1 in-place EC point addition: `(x2, y2) -> P + Q`.
+///
+/// `x2`: 256-bit register, pre = P.x in [0,q), post = (P+Q).x mod q.
+/// `y2`: 256-bit register, pre = P.y in [0,q), post = (P+Q).y mod q.
+/// `ox`, `oy`: 256-bit CLASSICAL (`BitId`) registers holding Q.x, Q.y in [0,q)
+///   (the other point, one value per shot -- loaded into transient quantum
+///   temps only at the off-peak coordinate steps, never resident at the GCD peak).
+/// The gcd apply's 256-bit scratch is internal to `mod_mul_inverse_in_place`.
+///
+/// Preconditions: P != Q and P != -Q (generic add, no doubling / identity).
+/// `x2` (= the inversion's GCD input `dx = P.x - Q.x`) must be a schedule
+/// FITTING input -- a width-truncating `dx` makes the forward GCD's
+/// register-shrink `zero_and_free` panic.
+pub fn ec_add(
+    circ: &mut B,
+    x2: &mut Vec<QubitId>,
+    y2: &[QubitId],
+    ox: &[BitId],
+    oy: &[BitId],
+) {
+    assert_eq!(x2.len(), N, "x2 is 256 bits");
+    assert_eq!(y2.len(), N, "y2 is 256 bits");
+    assert_eq!(ox.len(), N, "ox is 256 classical bits");
+    assert_eq!(oy.len(), N, "oy is 256 classical bits");
+
+    // Step 3/4: x2 -= ox ; y2 -= oy.  => (dx, dy).
+    coord_addsub(circ, x2, ox, true);
+    coord_addsub(circ, &y2[..N], oy, true);
+
+    // Step 6: y2 *= x2^-1 (gcd inversion). The multiplicand starts in y2[..N]
+    // (= dy); after the inverse apply y2 holds lambda = dy * dx^-1 mod q, and x2
+    // is restored to dx. `mod_mul_inverse_in_place` takes/returns the 256-bit x
+    // register; y2 and the internal tmp scratch are 256-bit.
+    let xv = std::mem::take(x2);
+    *x2 = mod_mul_inverse_in_place(circ, xv, y2, Direction::Inverse);
+
+    // Step 7: x2 += 3*ox.  => (P.x + 2*Q.x, lambda)  [x2 currently = dx = P.x-Q.x].
+    coord_add3x(circ, x2, ox);
+
+    // Step 10: x2 -= lambda^2 mod q.  (lambda = y2[..N]).
+    mod_square_sub_pm_secp256k1_symmetric(circ, &y2[..N], x2);
+
+    // Step 11: y2 *= x2 (gcd forward multiply). x2 restored to the post-square
+    // value; y2 = lambda * x2 mod q.
+    let xv = std::mem::take(x2);
+    *x2 = mod_mul_inverse_in_place(circ, xv, y2, Direction::Forward);
+
+    // Step 14: y2 -= oy.   Step 15: x2 := ox - x2.  => (P+Q).x.
+    coord_addsub(circ, &y2[..N], oy, true);
+    coord_rsub(circ, x2, ox);
+}

+/// Fused double-then-controlled-double: `y := y * 2 * (1 + s2) mod q`. `y.len() == n
+/// == 256`; the doubling uses two transient overflow bits (a 258-bit working view),
+/// not a persistent reg slot.
+pub fn fused_double_cdouble(circ: &mut B, s2: &QubitId, y: &[QubitId]) {
+    let n = 256usize;
+    assert_eq!(y.len(), n, "fused double expects 256-bit y (transient overflow)");
+    let _ = F_SECP256K1;
+    let hi = circ.alloc_qubit();
+    let hi2 = circ.alloc_qubit();
+    // 258-bit view: y[0..n] ++ hi (256) ++ hi2 (257).
+    let mut w: Vec<QubitId> = y.to_vec();
+    w.push(hi);
+    w.push(hi2);
+    // shift 1 (unconditional).
+    for i in (1..w.len()).rev() {
+        circ.swap(w[i], w[i - 1]);
+    }
+    // shift 2 (s2-controlled).
+    for i in (1..w.len()).rev() {
+        circ.cswap(*s2, w[i], w[i - 1]);
+    }
+    // combined fold: add (e+2d)*f into the low LSBS window. e=w[256], d=w[257].
+    // dirty borrow = the coordinate's own bits just above the fold window.
+    let borrow: Vec<QubitId> = y[LSBS..2 * LSBS - 1].to_vec();
+    fused_fold(circ, &w[n], &w[n + 1], &y[..LSBS], &borrow);
+    // clear carry bits via bit identity (post-fold w[0]==e, w[1]==d).
+    circ.cx(y[0], w[n]); // clear hi (e)
+    clear_and(circ, &w[n + 1], s2, &y[1]); // clear hi2 (d = s2 & y[1])
+    circ.zero_and_free(hi);
+    circ.zero_and_free(hi2);
+}

+/// Unconditional `output_reg -= lambda^2 mod q` (secp256k1), normal throughout.
+///
+/// `lambda` is `n = 256` bits (lambda < q); `output_reg` is `n = 256` bits and
+/// holds a value < q on entry (the EC-add keeps output reduced).
+///
+/// Stage 1: build the 2n-bit integer product `prod = lambda^2`
+/// with [`symmetric_square_into_prod`] (~n(n-1)/2 CCX).
+/// Stage 2 (reduce): `lambda < q < 2^256 => lambda^2 < q^2 < 2^512`,
+/// so `hi = prod>>256 < q`. With `2^256 == f (mod q)`, `lambda^2 == lo + f*hi`.
+/// Subtract `lo` from `output`, then for each set bit j of f walk `hi` in place
+/// by [`mod_double`] and subtract `hi*2^j mod q`; restore `hi` with the matched
+/// reverse doublings. Uses `arith::mod_sub` (uncontrolled normal Cuccaro
+/// register sub).
+/// Stage 3: uncompute `prod` (gate-reverse of Stage 1).
+///
+/// Value note (carried-over miss probability): each `mod_double` / `mod_sub`
+/// inherits `super::arith`'s `+f`-window carry drop -- a documented ~2^-PAD
+/// (PAD=21) per-fire approximation. The common path is exact; the only legal
+/// divergence is that rare large-input +f-window miss.
+pub fn mod_square_sub_pm_secp256k1_symmetric(circ: &mut B, lambda: &[QubitId], output_reg: &[QubitId]) {
+    let n = N;
+    assert_eq!(lambda.len(), n, "lambda must be n=256 bits (< q)");
+    assert_eq!(output_reg.len(), n, "output must be n=256 bits (< q)");
+
+    // Stage 1: prod = lambda^2 (integer, 2n bits).
+    let mut prod: Vec<QubitId> = Vec::with_capacity(2 * n);
+    symmetric_square_into_prod(circ, lambda, &mut prod);
+
+    // Stage 2: output -= (lo + f*hi) mod q, operating on prod's own halves.
+    //   lo = prod[0..n]                                  (n-bit, lo can be >= q)
+    //   hi = prod[n..2n]                                 (n-bit, hi < q)
+    // mod_double needs a 257-bit operand whose top bit is |0>; one inserted pad
+    // above hi supplies that overflow slot (restored, removed at the end).
+    {
+
+        // --- lo term: output -= lo mod q ---
+        // lo = prod[0..n] is a full integer < 2^256 (not pre-reduced), but
+        // mod_sub subtracts mod q, which is the value we want:
+        // lambda^2 mod q == (lo + f*hi) mod q == (lo mod q + ...).
+        // UNCONTROLLED: no |1>-gated register-sub CCX.
+        mod_sub(circ, &prod[0..n], output_reg);
+
+        let pad_hi = circ.alloc_qubit();
+        let mut hi_ext: Vec<QubitId> = prod[n..2 * n].to_vec();
+        hi_ext.push(pad_hi); // index 2n = overflow slot, |0>
+
+        // --- hi terms: output -= (hi*2^j mod q) for each f-bit j ---
+        let mut shifted = 0usize;
+        for &j in &F_BITS {
+            while shifted < j {
+                mod_double(circ, &hi_ext); // hi *= 2 mod q (257-bit, pad restored)
+                shifted += 1;
+            }
+            mod_sub(circ, &hi_ext[0..n], output_reg);
+        }
+        // restore hi to its raw value (matched-reverse the doublings). mod_double
+        // is built from a swap chain (self-inverse) + a +f window (NOT self-
+        // inverse), so a literal re-run does NOT undo it -- use the value-inverse
+        // mod_double_reverse (one halving per forward doubling).
+        while shifted > 0 {
+            mod_double_reverse(circ, &hi_ext);
+            shifted -= 1;
+        }
+
+        circ.zero_and_free(pad_hi);
+    }
+
+    // Stage 3: uncompute prod (gate-reverse of Stage 1).
+    symmetric_square_into_prod_reverse(circ, lambda, prod);
+}

